const petPanelDesktop = document.getElementById('petPanelDesktop');
const petPanelStock = document.getElementById('petPanelStock');
const petTabs = document.querySelectorAll('[data-pet-tab]');
function switchPetTab(mode) {
const stock = mode === 'stock';
if (petPanelDesktop) petPanelDesktop.classList.toggle('is-active', !stock);
if (petPanelStock) petPanelStock.classList.toggle('is-active', stock);
petTabs.forEach((b) => {
const a = b.dataset.petTab === mode;
b.classList.toggle('is-active', a);
b.setAttribute('aria-selected', String(a));
});
}
petTabs.forEach((b) => b.addEventListener('click', () => switchPetTab(b.dataset.petTab)));
const clockEl = document.getElementById('petLiveClock');
const dateEl = document.getElementById('petLiveDate');
const dayEl = document.getElementById('petLiveDay');
function syncClock() {
const d = new Date();
const days = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
if (clockEl) clockEl.textContent = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
if (dateEl) dateEl.textContent = `${d.getMonth() + 1}月${d.getDate()}日 ${days[d.getDay()]}`;
if (dayEl) dayEl.textContent = String(d.getDate());
}
syncClock();
setInterval(syncClock, 15000);
const wpRamPct = document.getElementById('wpRamPct');
const wpRamBar = document.getElementById('wpRamBar');
const wpCleanBtn = document.getElementById('wpCleanBtn');
const wpDockClean = document.getElementById('wpDockClean');
let ramCleaned = false;
function runRamClean() {
ramCleaned = !ramCleaned;
const pct = ramCleaned ? 22 : 64;
if (wpRamPct) wpRamPct.textContent = `${pct}%`;
if (wpRamBar) wpRamBar.style.width = `${pct}%`;
if (wpCleanBtn) wpCleanBtn.textContent = ramCleaned ? '✓ 已释放 3.8GB 内存' : '一键释放内存';
if (ramCleaned) showToast('⚡ 已释放 3.8GB 系统内存');
}
if (wpCleanBtn) wpCleanBtn.addEventListener('click', runRamClean);
if (wpDockClean) wpDockClean.addEventListener('click', runRamClean);
